import React from 'react';

const NavItemMobile = ({ onClick, icon, label }) => (
    <button onClick={onClick} className="flex items-center px-4 py-2 text-sm text-gray-700 dark:text-white whitespace-nowrap">
        {icon && <span className="mr-2">{icon}</span>}
        {label}
    </button>
);

export default NavItemMobile;
